package agents

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "codex" {
		return
	}
	Register(&Codex{})
	RegisterGate("codex", 2)
}

// Codex implements the E2E Agent interface for OpenAI's Codex CLI.
type Codex struct{}

type CodexSession struct {
	*TmuxSession

	home string
}

func (s *CodexSession) Home() string { return s.home }

func (c *Codex) Name() string               { return "codex" }
func (c *Codex) Binary() string             { return "codex" }
func (c *Codex) EntireAgent() string        { return "codex" }
func (c *Codex) PromptPattern() string      { return `›` }
func (c *Codex) TimeoutMultiplier() float64 { return 1.5 }

func (c *Codex) Bootstrap() error {
	if os.Getenv("CI") != "" && os.Getenv("OPENAI_API_KEY") == "" {
		return errors.New("OPENAI_API_KEY must be set on CI for Codex E2E tests")
	}
	return nil
}

func (c *Codex) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{"overloaded", "rate limit", "rate_limit", "503", "529", "ECONNRESET", "ETIMEDOUT"} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

// codexHome creates an isolated CODEX_HOME for a test run.
// Auth still works via OPENAI_API_KEY env var or symlinked auth.json.
//
// The directory lives under the user's home (not the system temp dir) because
// recent Codex versions refuse to install PATH helper binaries when CODEX_HOME
// sits under /tmp, which breaks subsequent tool calls.
func codexHome() (string, func(), error) {
	cache, err := os.UserCacheDir()
	if err != nil {
		return "", nil, fmt.Errorf("resolve user cache dir: %w", err)
	}
	base := filepath.Join(cache, "entire-e2e")
	if err := os.MkdirAll(base, 0o755); err != nil {
		return "", nil, fmt.Errorf("create codex home base %q: %w", base, err)
	}
	dir, err := os.MkdirTemp(base, "codex-home-*")
	if err != nil {
		return "", nil, fmt.Errorf("create temporary codex home under %q: %w", base, err)
	}
	return dir, func() { _ = os.RemoveAll(dir) }, nil
}

func (c *Codex) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	timeout := 60 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}
	promptCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	home, cleanup, err := codexHome()
	if err != nil {
		return Output{}, fmt.Errorf("create codex home: %w", err)
	}
	defer cleanup()

	absDir, err := filepath.Abs(dir)
	if err != nil {
		absDir = dir
	}
	if err := seedCodexHome(home, absDir); err != nil {
		return Output{}, fmt.Errorf("seed codex home: %w", err)
	}

	args := []string{"exec", "--dangerously-bypass-approvals-and-sandbox"}
	if cfg.Model != "" {
		args = append(args, "-m", cfg.Model)
	}
	args = append(args, prompt)

	env := append(filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CODEX_HOME"),
		"CODEX_HOME="+home,
	)

	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = env
	setupProcessGroup(cmd)
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	exitCode, err := runCapture(cmd, promptCtx)

	return Output{
		Command:  c.Binary() + " " + strings.Join(args[:len(args)-1], " ") + " " + fmt.Sprintf("%q", prompt),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (c *Codex) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("codex-test-%d", time.Now().UnixNano())

	home, cleanup, err := codexHome()
	if err != nil {
		return nil, fmt.Errorf("create codex home: %w", err)
	}

	absDir, err := filepath.Abs(dir)
	if err != nil {
		absDir = dir
	}
	if err := seedCodexHome(home, absDir); err != nil {
		cleanup()
		return nil, fmt.Errorf("seed codex home: %w", err)
	}

	s, err := c.startTmuxSession(name, dir, home, "codex", "--dangerously-bypass-approvals-and-sandbox")
	if err != nil {
		cleanup()
		return nil, err
	}
	s.OnClose(cleanup)

	// Dismiss startup dialogs (model upgrade prompts, etc.) until we reach
	// the input prompt. Similar to Claude's startup dialog handling.
	for range 5 {
		content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
		if waitErr != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for codex prompt: %w", waitErr)
		}
		if !strings.Contains(content, "press enter to confirm") &&
			!strings.Contains(content, "Use ↑/↓ to move") {
			break
		}
		_ = s.SendKeys("Enter")
		time.Sleep(500 * time.Millisecond)
	}

	return &CodexSession{TmuxSession: s, home: home}, nil
}

func (c *Codex) ResumeSession(ctx context.Context, dir, home, sessionID string) (Session, error) {
	_ = ctx
	name := fmt.Sprintf("codex-resume-%d", time.Now().UnixNano())

	s, err := c.startTmuxSession(name, dir, home, "codex", "--dangerously-bypass-approvals-and-sandbox", "resume", sessionID)
	if err != nil {
		return nil, err
	}

	// Dismiss any startup prompts until the input prompt appears.
	for range 5 {
		content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
		if waitErr != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for codex resumed prompt: %w", waitErr)
		}
		if !strings.Contains(content, "press enter to confirm") &&
			!strings.Contains(content, "Use ↑/↓ to move") {
			break
		}
		_ = s.SendKeys("Enter")
		time.Sleep(500 * time.Millisecond)
	}

	return &CodexSession{TmuxSession: s, home: home}, nil
}

func (c *Codex) startTmuxSession(name, dir, home string, args ...string) (*TmuxSession, error) {
	tmuxArgs := append([]string{"CODEX_HOME=" + home, "HOME=" + os.Getenv("HOME"), "TERM=" + os.Getenv("TERM")}, args...)
	return NewTmuxSession(name, dir, []string{"CODEX_HOME", "ENTIRE_TEST_TTY"}, "env", tmuxArgs...)
}

// seedCodexHome writes trust + feature flag config and links auth credentials
// so Codex loads the project's .codex/ layer and can authenticate.
func seedCodexHome(home, projectDir string) error {
	if err := os.MkdirAll(home, 0o750); err != nil {
		return err
	}

	// Write config with trust, feature flag, and pinned model to skip upgrade dialogs.
	model := os.Getenv("E2E_CODEX_MODEL")
	if model == "" {
		model = "gpt-5.4"
	}
	config := fmt.Sprintf("model = %q\n\n[features]\nhooks = true\n\n[projects.%q]\ntrust_level = \"trusted\"\n", model, projectDir)

	// Codex 0.129+ refuses to run unmanaged hooks until each one has a
	// trusted_hash entry in the user's config. Compute the hashes the same
	// way Codex does and pre-trust them — without this, every hook in
	// .codex/hooks.json sits as Untrusted and our hooks never fire under e2e.
	trustState, err := codexHookTrustState(projectDir)
	if err != nil {
		return fmt.Errorf("compute hook trust state: %w", err)
	}
	if trustState != "" {
		config += "\n" + trustState
	}

	if err := os.WriteFile(filepath.Join(home, "config.toml"), []byte(config), 0o600); err != nil {
		return err
	}

	if apiKey := os.Getenv("OPENAI_API_KEY"); apiKey != "" {
		return writeCodexAPIKeyAuth(home, apiKey)
	}

	// Symlink auth.json from the real ~/.codex/ so API credentials are available.
	if realHome, err := os.UserHomeDir(); err == nil {
		src := filepath.Join(realHome, ".codex", "auth.json")
		if _, err := os.Stat(src); err == nil {
			_ = os.Symlink(src, filepath.Join(home, "auth.json"))
		}
	}

	return nil
}

func writeCodexAPIKeyAuth(home, apiKey string) error {
	auth := struct {
		AuthMode     string `json:"auth_mode"`
		OpenAIAPIKey string `json:"OPENAI_API_KEY"`
	}{
		AuthMode:     "apikey",
		OpenAIAPIKey: apiKey,
	}

	data, err := json.MarshalIndent(auth, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal codex auth: %w", err)
	}
	data = append(data, '\n')

	if err := os.WriteFile(filepath.Join(home, "auth.json"), data, 0o600); err != nil {
		return fmt.Errorf("write codex auth: %w", err)
	}

	return nil
}

// Artifact capture is registered as a cleanup function.
//
// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
// so it can be inspected after the test. A symlink in the artifact dir
// points to the preserved repo.
func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
	t.Helper()

	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""

	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
	// creates nested subdirectories (TestName.../001/) whose structure
	// confuses some agents' (e.g. opencode) working-directory resolution.
	//
	// Codex refuses to operate from /tmp (e.g. "Refusing to create helper
	// binaries under temporary dir"), so for codex we place the repo under
	// $HOME/.cache/entire-e2e-repos/ instead.
	root := ""
	if agent.Name() == "codex" {
		cache, cerr := os.UserCacheDir()
		if cerr != nil {
			t.Fatalf("resolve user cache dir: %v", cerr)
		}
		root = filepath.Join(cache, "entire-e2e-repos")
		if err := os.MkdirAll(root, 0o755); err != nil {
			t.Fatalf("create e2e repo root %q: %v", root, err)
		}
	}
	dir, err := os.MkdirTemp(root, "e2e-repo-*")
	if err != nil {
		t.Fatalf("create temporary e2e repo under %q: %v", root, err)
	}
	if keepRepos {
		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
	} else {
		t.Cleanup(func() { os.RemoveAll(dir) })
	}

	// Resolve symlinks (macOS: /var -> /private/var) so paths match
	// what agent CLIs see when they resolve their own CWD.
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	Git(t, dir, "init")
	Git(t, dir, "config", "user.name", "E2E Test")
	Git(t, dir, "config", "user.email", "e2e@test.local")
	Git(t, dir, "config", "core.pager", "cat")
	Git(t, dir, "config", "core.autocrlf", "true")
	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")

	// External agents need external_agents enabled in settings before enable,
	// so the CLI can discover the agent binary via PATH during DiscoverAndRegister.
	if ea, ok := agent.(agents.ExternalAgent); ok && ea.IsExternalAgent() {
		entireDir := filepath.Join(dir, ".entire")
		if err := os.MkdirAll(entireDir, 0o755); err != nil {
			t.Fatalf("create .entire for external agent: %v", err)
		}
		if err := os.WriteFile(filepath.Join(entireDir, "settings.json"),
			[]byte("{\"external_agents\": true}\n"), 0o644); err != nil {
			t.Fatalf("write external_agents setting: %v", err)
		}
	}

	entire.Enable(t, dir, agent.EntireAgent())
	if agent.Name() == "gemini-cli" {
		setupGeminiTestHome(t, dir)
	}
	if agent.Name() == "factoryai-droid" {
		if err := configureDroidRepoSettings(dir); err != nil {
			t.Fatalf("configure droid repo settings: %v", err)
		}
	}
	// commit_linking=always ensures the prepare-commit-msg hook adds the
	// Entire-Checkpoint trailer unconditionally. This is needed because
	// interactive agents run inside tmux (CanPromptInteractively()=true) but
	// can't respond to prompts, and content detection may fail on the first
	// checkpoint when no shadow branch exists yet. Prompt-mode agents still
	// exercise the !CanPromptInteractively() fast path since they have no TTY
	// regardless of this setting.
	PatchSettings(t, dir, map[string]any{"log_level": "debug", "commit_linking": "always"})

	// Copilot CLI blocks on a "No copilot instructions found" notice in fresh
	// repos that lack .github/copilot-instructions.md, preventing the interactive
	// prompt from appearing.
	if agent.Name() == "copilot-cli" {
		ghDir := filepath.Join(dir, ".github")
		if err := os.MkdirAll(ghDir, 0o755); err != nil {
			t.Fatalf("create .github dir: %v", err)
		}
		if err := os.WriteFile(filepath.Join(ghDir, "copilot-instructions.md"), []byte("# E2E Test\n"), 0o644); err != nil {
			t.Fatalf("write copilot-instructions.md: %v", err)
		}
	}

	// OpenCode's non-interactive mode auto-rejects external_directory permission
	// since there's no user to prompt. Write a config to allow it.
	if agent.Name() == "opencode" {
		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
		}
		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
			t.Fatalf("write opencode.json: %v", err)
		}
	}

