package grok

import "encoding/json"

// Hook payload structs.
//
// Grok's config keys are PascalCase ("SessionStart") but the stdin payload
// spells hookEventName in snake_case ("session_start"), and every other field
// is camelCase. See cmd/entire/cli/agent/grok/AGENT.md for captured examples.

// baseHookInput holds the fields every Grok hook payload carries.
// promptId is absent on session-scoped events.
type baseHookInput struct {
	HookEventName  string `json:"hookEventName"`
	SessionID      string `json:"sessionId"`
	CWD            string `json:"cwd"`
	WorkspaceRoot  string `json:"workspaceRoot"`
	Timestamp      string `json:"timestamp"`
	PermissionMode string `json:"permissionMode"`
	PromptID       string `json:"promptId"`

	// TranscriptPath is the absolute path to the session's updates.jsonl.
	// Present on user_prompt_submit, stop, session_end, and the tool events;
	// absent on session_start, which carries Source instead.
	TranscriptPath string `json:"transcriptPath"`
}

type sessionStartInput struct {
	baseHookInput

	// Source is the start reason ("new", ...) and is the matcher field for
	// this event.
	Source string `json:"source"`
}

type userPromptSubmitInput struct {
	baseHookInput

	Prompt string `json:"prompt"`
}

// stopInput covers the Stop hook. Grok fires it twice per session: once for
// the turn (reason "end_turn", promptId set) and once at teardown (reason
// "shutdown", no promptId). Only the first is a TurnEnd — see isTurnStop.
type stopInput struct {
	baseHookInput

	Reason               string `json:"reason"`
	StopHookActive       bool   `json:"stopHookActive"`
	LastAssistantMessage string `json:"lastAssistantMessage"`
	SubagentType         string `json:"subagentType"`
}

// stopCancelledInput covers a turn interrupted, refused, or capped. Grok fires
// this INSTEAD of Stop, so it must still produce a TurnEnd or the turn's work
// is never checkpointed.
type stopCancelledInput struct {
	baseHookInput

	Reason        string `json:"reason"`
	CancelledBy   string `json:"cancelledBy"`
	CancelTrigger string `json:"cancelTrigger"`
	ReasonDetails string `json:"reasonDetails"`
	SubagentType  string `json:"subagentType"`
}

// stopFailureInput covers a turn ended by an API error. Also fires instead of
// Stop.
type stopFailureInput struct {
	baseHookInput

	Error        string `json:"error"`
	ErrorDetails string `json:"errorDetails"`
	SubagentType string `json:"subagentType"`
}

type sessionEndInput struct {
	baseHookInput

	Reason string `json:"reason"`
	// SubagentType is set when the ending session is a child session.
	SubagentType string `json:"subagentType"`
}

type compactInput struct {
	baseHookInput

	// Trigger is "manual" or "auto".
	Trigger string `json:"trigger"`
}

type subagentInput struct {
	baseHookInput

	SubagentType string `json:"subagentType"`
	Phase        string `json:"phase"`
}

type toolUseInput struct {
	baseHookInput

	ToolName   string          `json:"toolName"`
	ToolUseID  string          `json:"toolUseId"`
	ToolInput  json.RawMessage `json:"toolInput"`
	ToolResult json.RawMessage `json:"toolResult"`
}

// toolInputPaths are the file-path fields Grok's write/edit tools carry in
// toolInput.
type toolInputPaths struct {
	FilePath string `json:"file_path"`
	Path     string `json:"path"`
}

// toolResultPaths picks the absolute path out of a write/edit tool result,
// which is preferable to toolInput's repo-relative one.
type toolResultPaths struct {
	EditsApplied struct {
		AbsolutePath string `json:"absolute_path"`
	} `json:"EditsApplied"`
}

// Transcript envelope.
//
// updates.jsonl is NOT a stream of bare events: each line is a JSON-RPC
// envelope whose payload sits at params.update. Reading sessionUpdate off the
// top level yields nothing.

type transcriptLine struct {
	Timestamp int64  `json:"timestamp"`
	Method    string `json:"method"`
	Params    struct {
		SessionID string           `json:"sessionId"`
		Update    transcriptUpdate `json:"update"`
	} `json:"params"`
}

type transcriptUpdate struct {
	SessionUpdate string `json:"sessionUpdate"`

	// tool_call / tool_call_update
	ToolCallID string          `json:"toolCallId"`
	Status     string          `json:"status"`
	Kind       string          `json:"kind"`
	Title      string          `json:"title"`
	Content    []updateContent `json:"content"`
	Locations  []updateLoc     `json:"locations"`

	// user_message_chunk / agent_message_chunk
	Meta struct {
		ModelID string `json:"modelId"`
	} `json:"_meta"`

	// turn_completed
	PromptID   string          `json:"prompt_id"`
	StopReason string          `json:"stop_reason"`
	Usage      *transcriptUsge `json:"usage"`
}

// updateContent is one content block on a tool_call_update. A block of type
// "diff" is the authoritative signal that a file changed, and carries the
// absolute path.
type updateContent struct {
	Type string `json:"type"`
	Path string `json:"path"`
}

type updateLoc struct {
	Path string `json:"path"`
}

// transcriptUsge is turn_completed's usage block.
//
// InputTokens is the TOTAL input, cache inclusive — the fresh portion is
// InputTokens - CachedReadTokens - CacheCreationTokens. Verified against the
// same turn's headless JSON summary, which reports the fresh figure directly.
type transcriptUsge struct {
	InputTokens         int `json:"inputTokens"`
	OutputTokens        int `json:"outputTokens"`
	TotalTokens         int `json:"totalTokens"`
	CachedReadTokens    int `json:"cachedReadTokens"`
	CacheCreationTokens int `json:"cacheCreationTokens"`
	ReasoningTokens     int `json:"reasoningTokens"`
	ModelCalls          int `json:"modelCalls"`
}

// Package grok implements the Agent interface for xAI's Grok Build CLI.
//
// See AGENT.md in this directory for the researched hook and transcript
// contract, including captured payloads.
package grok

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameGrok, NewGrokAgent)
}

// GrokAgent implements the Agent interface for Grok Build.
//
//nolint:revive // GrokAgent is clearer than Agent in this context
type GrokAgent struct{}

// NewGrokAgent creates a new Grok agent instance.
func NewGrokAgent() agent.Agent { return &GrokAgent{} }

// Compile-time interface assertions.
var (
	_ agent.Agent              = (*GrokAgent)(nil)
	_ agent.HookSupport        = (*GrokAgent)(nil)
	_ agent.HookFreshness      = (*GrokAgent)(nil)
	_ agent.TranscriptAnalyzer = (*GrokAgent)(nil)
	_ agent.TokenCalculator    = (*GrokAgent)(nil)
	_ agent.ModelExtractor     = (*GrokAgent)(nil)
)

func (g *GrokAgent) Name() types.AgentName { return agent.AgentNameGrok }
func (g *GrokAgent) Type() types.AgentType { return agent.AgentTypeGrok }

func (g *GrokAgent) Description() string {
	return "Grok Build - xAI's terminal coding agent"
}

func (g *GrokAgent) IsPreview() bool { return true }

// ProtectedDirs returns directories Grok uses for repo-local config/state.
func (g *GrokAgent) ProtectedDirs() []string { return []string{".grok"} }

// DetectPresence reports whether Grok is configured in this repository.
func (g *GrokAgent) DetectPresence(ctx context.Context) (bool, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot = "."
	}
	if _, err := os.Stat(filepath.Join(repoRoot, ".grok")); err == nil {
		return true, nil
	}
	return false, nil
}

// GetSessionID extracts the session ID from hook input.
func (g *GrokAgent) GetSessionID(input *agent.HookInput) string { return input.SessionID }

// grokHome returns Grok's base directory, honoring the GROK_HOME override the
// E2E runner relies on for isolation.
func grokHome() (string, error) {
	if override := os.Getenv("GROK_HOME"); override != "" {
		return override, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}
	return filepath.Join(home, ".grok"), nil
}

// GetSessionDir returns the directory holding this repo's Grok sessions.
//
// Grok groups sessions by working directory, naming the group with the
// URL-encoded absolute path — every character escaped, separators included, so
// "/a/b" becomes "%2Fa%2Fb". Verified against a live session.
//
// Grok switches to a slug-plus-hash name (recording the real path in a .cwd
// file inside the group) once the encoded name would exceed 255 bytes. That
// branch is not reproduced here: every hook payload except session_start
// carries transcriptPath outright, so this path is a fallback rather than the
// primary resolution route.
func (g *GrokAgent) GetSessionDir(repoPath string) (string, error) {
	home, err := grokHome()
	if err != nil {
		return "", err
	}
	abs, err := filepath.Abs(repoPath)
	if err != nil {
		abs = repoPath
	}
	return filepath.Join(home, "sessions", encodeCWD(abs)), nil
}

// GetSessionBaseDir returns the directory containing all per-project session
// groups.
func (g *GrokAgent) GetSessionBaseDir() (string, error) {
	home, err := grokHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, "sessions"), nil
}

// encodeCWD percent-encodes every byte url.QueryEscape would, but with "/"
// escaped and " " rendered as %20 rather than "+", matching what Grok writes.
func encodeCWD(path string) string {
	escaped := url.PathEscape(path)
	// PathEscape leaves "/" and a few sub-delims alone; Grok escapes them.
	var out []byte
	for i := 0; i < len(escaped); i++ {
		switch c := escaped[i]; c {
		case '/':
			out = append(out, '%', '2', 'F')
		default:
			out = append(out, c)
		}
	}
	return string(out)
}

// ResolveSessionFile returns the transcript path for a session.
// Grok stores it as <sessionDir>/<session-id>/updates.jsonl.
func (g *GrokAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	return filepath.Join(sessionDir, agentSessionID, transcriptFileName)
}

// transcriptFileName is Grok's authoritative conversation log. The sibling
// chat_history.jsonl holds raw model-facing messages and is deliberately not
// used: updates.jsonl is what the docs call the source of truth and what
// /resume replays.
const transcriptFileName = "updates.jsonl"

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (g *GrokAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // path comes from Grok hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits the JSONL transcript at line boundaries.
func (g *GrokAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks.
func (g *GrokAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

// ReadSession reads a session from Grok's storage.
func (g *GrokAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}
	data, err := os.ReadFile(input.SessionRef) //nolint:gosec // path comes from Grok hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	files, _ := modifiedFilesFrom(data, 0)
	return &agent.AgentSession{
		SessionID:     input.SessionID,
		AgentName:     g.Name(),
		SessionRef:    input.SessionRef,
		StartTime:     time.Now(),
		NativeData:    data,
		ModifiedFiles: files,
	}, nil
}

// WriteSession writes a session back to Grok's storage for resumption.
func (g *GrokAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}
	if session.AgentName != "" && session.AgentName != g.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
	}
	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}
	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}
	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
		return fmt.Errorf("failed to create session dir: %w", err)
	}
	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}
	return nil
}

// FormatResumeCommand returns the command to resume a Grok session.
func (g *GrokAgent) FormatResumeCommand(sessionID string) string {
	return "grok --resume " + sessionID
}

package grok

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Hook verbs. These become subcommands under `entire hooks grok`.
const (
	HookNameSessionStart     = "session-start"
	HookNameSessionEnd       = "session-end"
	HookNameUserPromptSubmit = "user-prompt-submit"
	HookNameStop             = "stop"
	HookNameStopCancelled    = "stop-cancelled"
	HookNameStopFailure      = "stop-failure"
	HookNamePreCompact       = "pre-compact"
	HookNameSubagentStart    = "subagent-start"
	HookNameSubagentStop     = "subagent-stop"
	HookNamePostToolUse      = "post-tool-use"
)

// hooksFileRelPath is the file Entire owns outright.
//
// Grok merges every *.json under .grok/hooks/, so Entire gets its own file
// rather than editing one a user also maintains. Install is a whole-file write
// and uninstall is a delete — no read-modify-write, and no way to clobber a
// user's own hooks.
var hooksFileRelPath = filepath.Join(".grok", "hooks", "entire.json")

// entireMarker identifies the file as Entire-owned.
const entireMarker = "entire hooks grok "

// grokEventForHook maps an Entire hook verb to the PascalCase event name Grok
// expects as a config key. The stdin payload spells the same event in
// snake_case; see types.go.
var grokEventForHook = map[string]string{
	HookNameSessionStart:     "SessionStart",
	HookNameSessionEnd:       "SessionEnd",
	HookNameUserPromptSubmit: "UserPromptSubmit",
	HookNameStop:             "Stop",
	HookNameStopCancelled:    "StopCancelled",
	HookNameStopFailure:      "StopFailure",
	HookNamePreCompact:       "PreCompact",
	HookNameSubagentStart:    "SubagentStart",
	HookNameSubagentStop:     "SubagentStop",
	HookNamePostToolUse:      "PostToolUse",
}

// hookInstallOrder keeps the rendered config deterministic so
// GeneratedHookFileState can compare it byte-for-byte.
var hookInstallOrder = []string{
	HookNameSessionStart,
	HookNameUserPromptSubmit,
	HookNamePostToolUse,
	HookNameStop,
	HookNameStopCancelled,
	HookNameStopFailure,
	HookNameSubagentStart,
	HookNameSubagentStop,
	HookNamePreCompact,
	HookNameSessionEnd,
}

// hookTimeoutSeconds bounds each hook. Grok defaults non-gate events to 5s,
// which is tight for a cold `entire` invocation on a large repo, so ask for
// more. Stop and SubagentStop are gates and already default to 600s.
const hookTimeoutSeconds = 30

// HookNames returns the hook verbs Grok supports.
func (g *GrokAgent) HookNames() []string {
	out := make([]string, len(hookInstallOrder))
	copy(out, hookInstallOrder)
	return out
}

// GetSupportedHooks returns the hook types Grok supports.
func (g *GrokAgent) GetSupportedHooks() []agent.HookType {
	return []agent.HookType{
		agent.HookSessionStart,
		agent.HookSessionEnd,
		agent.HookUserPromptSubmit,
		agent.HookStop,
		agent.HookPostToolUse,
	}
}

// grokHookCommand is one command entry inside a matcher group.
type grokHookCommand struct {
	Type    string `json:"type"`
	Command string `json:"command"`
	Timeout int    `json:"timeout,omitempty"`
}

// grokHookGroup is one matcher group for an event.
type grokHookGroup struct {
	Matcher string            `json:"matcher"`
	Hooks   []grokHookCommand `json:"hooks"`
}

// grokHooksFile is the whole config. Grok reuses Claude Code's nested shape
// verbatim.
type grokHooksFile struct {
	Hooks map[string][]grokHookGroup `json:"hooks"`
}

func hooksPath(ctx context.Context) (string, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		//nolint:forbidigo // explicit fallback when WorktreeRoot fails
		root, err = os.Getwd()
		if err != nil {
			return "", fmt.Errorf("resolve repo root: %w", err)
		}
	}
	return filepath.Join(root, hooksFileRelPath), nil
}

// renderHooks returns the full config content Entire installs.
func renderHooks(ctx context.Context) (string, error) {
	useWindowsHooks := agent.UseWindowsProductionHooks(ctx)

	file := grokHooksFile{Hooks: map[string][]grokHookGroup{}}
	for _, verb := range hookInstallOrder {
		event, ok := grokEventForHook[verb]
		if !ok {
			continue
		}
		cmd := agent.WrapProductionSilentHookCommandForOS(entireMarker+verb, useWindowsHooks)
		file.Hooks[event] = []grokHookGroup{{
			Matcher: "",
			Hooks:   []grokHookCommand{{Type: "command", Command: cmd, Timeout: hookTimeoutSeconds}},
		}}
	}

	out, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
	if err != nil {
		return "", fmt.Errorf("marshal grok hooks: %w", err)
	}
	return string(out), nil
}

// InstallHooks writes .grok/hooks/entire.json.
// Returns 1 when the file was written, 0 when it was already current.
//
// A file at that path that is not recognisably Entire's is left alone unless
// force is set, so a user who happens to keep their own entire.json there does
// not lose it.
func (g *GrokAgent) InstallHooks(ctx context.Context, force bool) (int, error) {
	path, err := hooksPath(ctx)
	if err != nil {
		return 0, err
	}
	content, err := renderHooks(ctx)
	if err != nil {
		return 0, err
	}

	if !force {
		existing, readErr := os.ReadFile(path) //nolint:gosec // path from validated repo root
		switch {
		case readErr == nil && string(existing) == content:
			return 0, nil
		case readErr == nil && !strings.Contains(string(existing), entireMarker):
			return 0, fmt.Errorf("refusing to overwrite foreign file at %s; remove it or pass --force", path)
		}
	}

	//nolint:gosec // G301: grok reads the directory; standard 0755 permissions
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return 0, fmt.Errorf("create grok hooks dir: %w", err)
	}
	//nolint:gosec // G306: grok reads the file; standard 0644 permissions
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		return 0, fmt.Errorf("write grok hooks: %w", err)
	}
	return 1, nil
}

// UninstallHooks removes Entire's hooks file. A foreign file at that path is
// left in place.
func (g *GrokAgent) UninstallHooks(ctx context.Context) error {
	path, err := hooksPath(ctx)
	if err != nil {
		return err
	}
	data, readErr := os.ReadFile(path) //nolint:gosec // path from validated repo root
	if readErr != nil {
		return nil //nolint:nilerr // nothing installed means nothing to remove
	}
	if !strings.Contains(string(data), entireMarker) {
		return nil
	}
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("remove grok hooks: %w", err)
	}
	return nil
}

// AreHooksInstalled reports whether Entire's hooks file is present.
func (g *GrokAgent) AreHooksInstalled(ctx context.Context) bool {
	path, err := hooksPath(ctx)
	if err != nil {
		return false
	}
	data, err := os.ReadFile(path) //nolint:gosec // path from validated repo root
	if err != nil {
		return false
	}
	return strings.Contains(string(data), entireMarker)
}

// CheckHookConfig reports whether the installed config matches what
// InstallHooks would write today.
//
// This matters for Grok specifically: .grok/hooks/entire.json is a repo-local
// file teams commonly commit so every clone is checkpointed without each person
// running enable. A committed config goes stale as hook verbs change, and
// AreHooksInstalled keeps returning true because the marker is still there —
// while Grok's own hook execution fails open, so nothing surfaces the drift.
func (g *GrokAgent) CheckHookConfig(ctx context.Context) agent.HookConfigState {
	path, err := hooksPath(ctx)
	if err != nil {
		return agent.HooksAbsent
	}
	content, err := renderHooks(ctx)
	if err != nil {
		return agent.HooksAbsent
	}
	return agent.GeneratedHookFileState(path, entireMarker, content)
}

package grok

import (
	"context"
	"encoding/json"
	"io"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// ParseHookEvent translates a Grok hook into a normalized lifecycle Event.
// Returns nil when the hook carries no lifecycle significance.
func (g *GrokAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		return g.parseSessionStart(ctx, stdin)
	case HookNameUserPromptSubmit:
		return g.parseTurnStart(stdin)
	case HookNameStop:
		return g.parseStop(stdin)
	case HookNameStopCancelled:
		return g.parseStopCancelled(stdin)
	case HookNameStopFailure:
		return g.parseStopFailure(stdin)
	case HookNameSessionEnd:
		return g.parseSessionEnd(stdin)
	case HookNamePreCompact:
		return g.parseCompaction(stdin)
	case HookNameSubagentStart:
		return g.parseSubagentStart(stdin)
	case HookNameSubagentStop:
		return g.parseSubagentStop(stdin)
	case HookNamePostToolUse:
		return g.parseToolUse(stdin)
	default:
		return nil, nil //nolint:nilnil // unknown hooks have no lifecycle action
	}
}

// parseTime converts Grok's RFC3339 timestamp, falling back to now.
func parseTime(s string) time.Time {
	if s == "" {
		return time.Now()
	}
	if t, err := time.Parse(time.RFC3339, s); err == nil {
		return t
	}
	return time.Now()
}

// sessionRef resolves the transcript path. Every hook but session_start
// supplies transcriptPath outright, which is authoritative; only session_start
// needs the path derived from cwd + session id.
func (g *GrokAgent) sessionRef(ctx context.Context, in baseHookInput) string {
	if in.TranscriptPath != "" {
		return in.TranscriptPath
	}
	cwd := in.WorkspaceRoot
	if cwd == "" {
		cwd = in.CWD
	}
	if cwd == "" || in.SessionID == "" {
		return ""
	}
	dir, err := g.GetSessionDir(cwd)
	if err != nil {
		logging.Warn(ctx, "grok: failed to resolve session dir", "err", err)
		return ""
	}
	return g.ResolveSessionFile(dir, in.SessionID)
}

func (g *GrokAgent) parseSessionStart(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionStartInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  raw.SessionID,
		SessionRef: g.sessionRef(ctx, raw.baseHookInput),
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

func (g *GrokAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[userPromptSubmitInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Prompt:     raw.Prompt,
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

// isTeardownStop reports whether a Stop payload is the observe-only one Grok
// fires at session teardown rather than at the end of a turn.
//
// Grok fires Stop twice per session: once for the turn (reason "end_turn",
// promptId set, lastAssistantMessage populated) and once during shutdown
// (reason "shutdown", no promptId). Treating the second as a TurnEnd mints a
// duplicate, contentless checkpoint on every session. Both signals are checked
// because reason is documented to also take "channel_closed" at teardown, and
// only the turn-scoped payload carries a promptId.
func isTeardownStop(reason, promptID string) bool {
	return reason == "shutdown" || reason == "channel_closed" || promptID == ""
}

func (g *GrokAgent) parseStop(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[stopInput](stdin)
	if err != nil {
		return nil, err
	}
	if isTeardownStop(raw.Reason, raw.PromptID) {
		return nil, nil //nolint:nilnil // teardown Stop is observe-only; SessionEnd covers it
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

// parseStopCancelled maps an interrupted turn to TurnEnd.
//
// Grok fires StopCancelled INSTEAD of Stop when a turn is interrupted, has a
// permission prompt declined, hits --max-turns, or bails out for lack of
// progress. Without this mapping every such turn's work goes uncheckpointed,
// which is the common case for a user pressing Ctrl+C mid-edit.
func (g *GrokAgent) parseStopCancelled(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[stopCancelledInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

// parseStopFailure maps an API-errored turn to TurnEnd, for the same reason as
// parseStopCancelled: Stop does not fire.
func (g *GrokAgent) parseStopFailure(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[stopFailureInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

func (g *GrokAgent) parseSessionEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionEndInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionEnd,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

func (g *GrokAgent) parseCompaction(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[compactInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.Compaction,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

func (g *GrokAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:         agent.SubagentStart,
		SessionID:    raw.SessionID,
		SessionRef:   raw.TranscriptPath,
		SubagentType: raw.SubagentType,
		Timestamp:    parseTime(raw.Timestamp),
	}, nil
}

// parseSubagentStop maps Grok's subagent completion to SubagentEnd.
//
// Final is true because Grok fires SubagentStop once, at real completion —
// there is no separate launch stub to disambiguate from, unlike Claude Code's
// two-signal background-task model.
func (g *GrokAgent) parseSubagentStop(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[subagentInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:         agent.SubagentEnd,
		SessionID:    raw.SessionID,
		SessionRef:   raw.TranscriptPath,
		SubagentType: raw.SubagentType,
		Final:        true,
		Timestamp:    parseTime(raw.Timestamp),
	}, nil
}

// parseToolUse reports mid-turn file writes so the framework can attribute
// files to a commit the agent makes before its turn ends.
//
// Returns nil for tools that touched no file, which is most of them.
func (g *GrokAgent) parseToolUse(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[toolUseInput](stdin)
	if err != nil {
		return nil, err
	}
	path := toolUsePath(raw)
	if path == "" {
		return nil, nil //nolint:nilnil // no file touched, no lifecycle action
	}
	return &agent.Event{
		Type:          agent.ToolUse,
		SessionID:     raw.SessionID,
		SessionRef:    raw.TranscriptPath,
		ToolUseID:     raw.ToolUseID,
		CWD:           raw.CWD,
		ModifiedFiles: []string{path},
		Timestamp:     parseTime(raw.Timestamp),
	}, nil
}

// toolUsePath extracts the file a write/edit tool touched, preferring the
// absolute path in the result over the repo-relative one in the input.
func toolUsePath(raw *toolUseInput) string {
	if len(raw.ToolResult) > 0 {
		var res toolResultPaths
		if err := json.Unmarshal(raw.ToolResult, &res); err == nil {
			if p := res.EditsApplied.AbsolutePath; p != "" {
				return p
			}
		}
	}
	if len(raw.ToolInput) > 0 {
		var in toolInputPaths
		if err := json.Unmarshal(raw.ToolInput, &in); err == nil {
			if in.FilePath != "" {
				return in.FilePath
			}
			if in.Path != "" {
				return in.Path
			}
		}
	}
	return ""
}

package grok

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// GetTranscriptPosition returns the line count of a Grok transcript.
// updates.jsonl is JSONL, so position is lines.
func (g *GrokAgent) GetTranscriptPosition(path string) (int, error) {
	if path == "" {
		return 0, nil
	}
	file, err := os.Open(path) //nolint:gosec // path comes from Grok transcript location
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("failed to open transcript file: %w", err)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	lines := 0
	for {
		line, err := reader.ReadBytes('\n')
		if err != nil {
			if err == io.EOF {
				if len(line) > 0 {
					lines++
				}
				break
			}
			return 0, fmt.Errorf("failed to read transcript: %w", err)
		}
		lines++
	}
	return lines, nil
}

// ExtractModifiedFilesFromOffset returns files Grok changed after startOffset
// lines, along with the transcript's current line count.
func (g *GrokAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
	if path == "" {
		return nil, 0, nil
	}
	data, err := os.ReadFile(path) //nolint:gosec // path comes from Grok transcript location
	if err != nil {
		if os.IsNotExist(err) {
			return nil, 0, nil
		}
		return nil, 0, fmt.Errorf("failed to open transcript file: %w", err)
	}
	found, lines := modifiedFilesFrom(data, startOffset)
	return found, lines, nil
}

// modifiedFilesFrom walks the transcript from startOffset and returns the
// deduplicated set of files Grok wrote, plus the total line count.
//
// A `diff` content block on a tool_call_update is the authoritative signal that
// a file changed: it is emitted only for an actual edit and carries the
// absolute path. locations[] is the fallback — it is present on the same
// updates but holds a repo-relative path, and read-only tools populate it too,
// so it is consulted only when no diff block named a path for that tool call.
func modifiedFilesFrom(data []byte, startOffset int) ([]string, int) {
	var (
		out      []string
		seen     = map[string]bool{}
		lineNum  int
		fallback = map[string][]string{} // toolCallID -> relative paths
		diffed   = map[string]bool{}     // toolCallID -> saw a diff block
	)

	add := func(p string) {
		if p == "" || seen[p] {
			return
		}
		seen[p] = true
		out = append(out, p)
	}

	for _, raw := range splitJSONL(data) {
		lineNum++
		if lineNum <= startOffset {
			continue
		}
		var line transcriptLine
		if err := json.Unmarshal(raw, &line); err != nil {
			continue // skip malformed lines
		}
		u := line.Params.Update
		if u.SessionUpdate != "tool_call_update" && u.SessionUpdate != "tool_call" {
			continue
		}
		for _, c := range u.Content {
			if c.Type == "diff" && c.Path != "" {
				diffed[u.ToolCallID] = true
				add(c.Path)
			}
		}
		for _, l := range u.Locations {
			if l.Path != "" {
				fallback[u.ToolCallID] = append(fallback[u.ToolCallID], l.Path)
			}
		}
	}

	for id, paths := range fallback {
		if diffed[id] {
			continue
		}
		for _, p := range paths {
			add(p)
		}
	}

	// Count any lines before startOffset that the loop skipped.
	return out, lineNum
}

// splitJSONL splits raw JSONL into non-empty lines.
func splitJSONL(data []byte) [][]byte {
	var out [][]byte
	start := 0
	for i := 0; i < len(data); i++ {
		if data[i] != '\n' {
			continue
		}
		if line := trimCR(data[start:i]); len(line) > 0 {
			out = append(out, line)
		}
		start = i + 1
	}
	if start < len(data) {
		if line := trimCR(data[start:]); len(line) > 0 {
			out = append(out, line)
		}
	}
	return out
}

func trimCR(b []byte) []byte {
	if len(b) > 0 && b[len(b)-1] == '\r' {
		b = b[:len(b)-1]
	}
	return b
}

// CalculateTokenUsage sums the turn_completed usage blocks after fromOffset.
//
// Grok reports inputTokens as the TOTAL input, cache inclusive, so the fresh
// portion is derived here — the same shape Cursor needs. Verified against the
// headless JSON summary for the same turn, which reports the fresh figure
// directly.
func (g *GrokAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
	var (
		total   agent.TokenUsage
		lineNum int
		any     bool
	)
	for _, raw := range splitJSONL(transcriptData) {
		lineNum++
		if lineNum <= fromOffset {
			continue
		}
		var line transcriptLine
		if err := json.Unmarshal(raw, &line); err != nil {
			continue
		}
		u := line.Params.Update
		if u.SessionUpdate != "turn_completed" || u.Usage == nil {
			continue
		}
		any = true
		fresh := u.Usage.InputTokens - u.Usage.CachedReadTokens - u.Usage.CacheCreationTokens
		if fresh < 0 {
			fresh = 0
		}
		total.InputTokens += fresh
		total.CacheReadTokens += u.Usage.CachedReadTokens
		total.CacheCreationTokens += u.Usage.CacheCreationTokens
		total.OutputTokens += u.Usage.OutputTokens
		calls := u.Usage.ModelCalls
		if calls == 0 {
			calls = 1
		}
		total.APICallCount += calls
	}
	if !any {
		return nil, nil //nolint:nilnil // no usage data is "unknown", not zero
	}
	return &total, nil
}

// ExtractModel returns the model Grok used, read from the per-message _meta
// Grok stamps on message chunks. Hook payloads carry no model field, so the
// transcript is the only source.
func (g *GrokAgent) ExtractModel(transcriptData []byte) (string, error) {
	for _, raw := range splitJSONL(transcriptData) {
		var line transcriptLine
		if err := json.Unmarshal(raw, &line); err != nil {
			continue
		}
		if m := line.Params.Update.Meta.ModelID; m != "" {
			return m, nil
		}
	}
	return "", nil
}

