package grok

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// fixture returns a golden hook payload captured from a real Grok 1.0.5
// session (see AGENT.md).
func fixture(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}
	return data
}

func parse(t *testing.T, hookName, fixtureName string) *agent.Event {
	t.Helper()
	g := &GrokAgent{}
	ev, err := g.ParseHookEvent(context.Background(), hookName, bytes.NewReader(fixture(t, fixtureName)))
	if err != nil {
		t.Fatalf("ParseHookEvent(%s): %v", hookName, err)
	}
	return ev
}

func TestParseHookEvent_EventTypeMapping(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		hook     string
		fixture  string
		wantType agent.EventType
	}{
		{"session start", HookNameSessionStart, "session_start.json", agent.SessionStart},
		{"prompt submit", HookNameUserPromptSubmit, "user_prompt_submit.json", agent.TurnStart},
		{"turn stop", HookNameStop, "stop_turn.json", agent.TurnEnd},
		{"session end", HookNameSessionEnd, "session_end.json", agent.SessionEnd},
		{"tool use", HookNamePostToolUse, "post_tool_use.json", agent.ToolUse},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			ev := parse(t, tt.hook, tt.fixture)
			if ev == nil {
				t.Fatalf("%s: got nil event, want %v", tt.hook, tt.wantType)
			}
			if ev.Type != tt.wantType {
				t.Errorf("Type = %v, want %v", ev.Type, tt.wantType)
			}
			if ev.SessionID != "01a03a9f-0f3b-78d2-bad3-cf2ad4e0ff2e" {
				t.Errorf("SessionID = %q", ev.SessionID)
			}
		})
	}
}

// TestParseHookEvent_TeardownStopIsNotATurn locks in the discriminator between
// Grok's two Stop invocations. Both fixtures are real payloads from a single
// session: the turn-scoped one and the teardown one that follows SessionEnd.
// Without this split every Grok session mints a duplicate, contentless
// checkpoint.
func TestParseHookEvent_TeardownStopIsNotATurn(t *testing.T) {
	t.Parallel()

	if ev := parse(t, HookNameStop, "stop_turn.json"); ev == nil || ev.Type != agent.TurnEnd {
		t.Fatalf("turn stop: got %v, want TurnEnd", ev)
	}
	if ev := parse(t, HookNameStop, "stop_teardown.json"); ev != nil {
		t.Errorf("teardown stop: got %v, want nil (no lifecycle action)", ev.Type)
	}
}

func TestIsTeardownStop(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		reason   string
		promptID string
		want     bool
	}{
		{"real turn", "end_turn", "p-1", false},
		{"shutdown", "shutdown", "", true},
		{"channel closed", "channel_closed", "", true},
		{"missing prompt id", "end_turn", "", true},
		{"shutdown with prompt id", "shutdown", "p-1", true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := isTeardownStop(tt.reason, tt.promptID); got != tt.want {
				t.Errorf("isTeardownStop(%q, %q) = %v, want %v", tt.reason, tt.promptID, got, tt.want)
			}
		})
	}
}

// TestParseHookEvent_CancelledAndFailedTurnsEndTheTurn guards the mapping that
// is easiest to omit: Grok fires StopCancelled/StopFailure INSTEAD of Stop, so
// without these an interrupted or rate-limited turn is never checkpointed.
func TestParseHookEvent_CancelledAndFailedTurnsEndTheTurn(t *testing.T) {
	t.Parallel()

	cancelled := []byte(`{"hookEventName":"stop_cancelled","sessionId":"s1","promptId":"p1",
		"transcriptPath":"/tmp/updates.jsonl","reason":"user_interrupt","cancelledBy":"user","cancelTrigger":"ctrl_c"}`)
	failed := []byte(`{"hookEventName":"stop_failure","sessionId":"s1","promptId":"p1",
		"transcriptPath":"/tmp/updates.jsonl","error":"rate_limit"}`)

	g := &GrokAgent{}
	for _, tc := range []struct {
		hook string
		body []byte
	}{
		{HookNameStopCancelled, cancelled},
		{HookNameStopFailure, failed},
	} {
		ev, err := g.ParseHookEvent(context.Background(), tc.hook, bytes.NewReader(tc.body))
		if err != nil {
			t.Fatalf("%s: %v", tc.hook, err)
		}
		if ev == nil || ev.Type != agent.TurnEnd {
			t.Errorf("%s: got %v, want TurnEnd", tc.hook, ev)
		}
	}
}

func TestParseHookEvent_SubagentStopIsFinal(t *testing.T) {
	t.Parallel()

	body := []byte(`{"hookEventName":"subagent_stop","sessionId":"s1","transcriptPath":"/tmp/u.jsonl","subagentType":"worker","phase":"end"}`)
	g := &GrokAgent{}
	ev, err := g.ParseHookEvent(context.Background(), HookNameSubagentStop, bytes.NewReader(body))
	if err != nil {
		t.Fatalf("subagent stop: %v", err)
	}
	if ev == nil || ev.Type != agent.SubagentEnd {
		t.Fatalf("got %v, want SubagentEnd", ev)
	}
	// Grok fires SubagentStop once, at true completion — there is no launch
	// stub to disambiguate from, so Final must be set.
	if !ev.Final {
		t.Error("Final = false, want true (Grok has no separate launch stub)")
	}
}

func TestParseHookEvent_UnknownHookReturnsNil(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	ev, err := g.ParseHookEvent(context.Background(), "not-a-real-hook", bytes.NewReader([]byte(`{}`)))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if ev != nil {
		t.Errorf("got %v, want nil", ev.Type)
	}
}

func TestParseHookEvent_MalformedJSONErrors(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	if _, err := g.ParseHookEvent(context.Background(), HookNameStop, bytes.NewReader([]byte(`{not json`))); err == nil {
		t.Error("expected an error for malformed JSON")
	}
}

// TestParseHookEvent_TranscriptPathIsUsed pins the field name. Grok spells it
// camelCase; binding snake_case (as the Claude Code payload does) silently
// yields an empty transcript path and a checkpoint with no content.
func TestParseHookEvent_TranscriptPathIsUsed(t *testing.T) {
	t.Parallel()

	ev := parse(t, HookNameStop, "stop_turn.json")
	if ev == nil {
		t.Fatal("nil event")
	}
	if ev.SessionRef == "" {
		t.Fatal("SessionRef is empty; transcriptPath was not parsed")
	}
	if filepath.Base(ev.SessionRef) != transcriptFileName {
		t.Errorf("SessionRef = %q, want it to end in %s", ev.SessionRef, transcriptFileName)
	}
}

func TestParseToolUse_ExtractsAbsolutePath(t *testing.T) {
	t.Parallel()

	ev := parse(t, HookNamePostToolUse, "post_tool_use.json")
	if ev == nil {
		t.Fatal("nil event")
	}
	if len(ev.ModifiedFiles) != 1 {
		t.Fatalf("ModifiedFiles = %v, want exactly one", ev.ModifiedFiles)
	}
	// The result's absolute_path is preferred over toolInput's relative
	// file_path, so the framework does not have to guess a base directory.
	if !filepath.IsAbs(ev.ModifiedFiles[0]) {
		t.Errorf("ModifiedFiles[0] = %q, want an absolute path", ev.ModifiedFiles[0])
	}
	if filepath.Base(ev.ModifiedFiles[0]) != "hello.txt" {
		t.Errorf("ModifiedFiles[0] = %q, want basename hello.txt", ev.ModifiedFiles[0])
	}
}

func TestParseToolUse_NoFileTouchedReturnsNil(t *testing.T) {
	t.Parallel()

	body := []byte(`{"hookEventName":"post_tool_use","sessionId":"s1","toolName":"run_terminal_command","toolInput":{"command":"ls"}}`)
	g := &GrokAgent{}
	ev, err := g.ParseHookEvent(context.Background(), HookNamePostToolUse, bytes.NewReader(body))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if ev != nil {
		t.Errorf("got %v, want nil for a tool that touched no file", ev.Type)
	}
}

func TestUnwrapPrompt(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		in   string
		want string
	}{
		{
			name: "strips the envelope",
			in:   "<user_query>\nCreate a file named hello.txt.\n</user_query>",
			want: "Create a file named hello.txt.",
		},
		{
			name: "leaves an unwrapped prompt alone",
			in:   "Create a file named hello.txt.",
			want: "Create a file named hello.txt.",
		},
		{
			name: "keeps context outside the envelope",
			in:   "Context line\n<user_query>\nDo the thing.\n</user_query>\nTrailing note",
			want: "Context line\n\nDo the thing.\n\nTrailing note",
		},
		{
			name: "unterminated envelope is left alone",
			in:   "<user_query>\nDo the thing.",
			want: "<user_query>\nDo the thing.",
		},
		{
			name: "empty envelope falls back to the original",
			in:   "<user_query></user_query>",
			want: "<user_query></user_query>",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := unwrapPrompt(tt.in); got != tt.want {
				t.Errorf("unwrapPrompt(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

// TestParseTurnStart_PromptIsUnwrapped ties the unwrapping to the real payload:
// the captured prompt really does arrive inside <user_query>.
func TestParseTurnStart_PromptIsUnwrapped(t *testing.T) {
	t.Parallel()

	ev := parse(t, HookNameUserPromptSubmit, "user_prompt_submit.json")
	if ev == nil {
		t.Fatal("nil event")
	}
	if ev.Prompt == "" {
		t.Fatal("Prompt is empty")
	}
	if got := ev.Prompt; got[0] == '<' {
		t.Errorf("Prompt still wrapped: %q", got)
	}
	if want := "Create a file named hello.txt containing exactly the word hello. Then stop."; ev.Prompt != want {
		t.Errorf("Prompt = %q, want %q", ev.Prompt, want)
	}
}

package grok

import (
	"os"
	"path/filepath"
	"testing"
)

// realTranscript is a complete updates.jsonl from a real Grok 1.0.5 session
// (one turn, two model calls, one file write).
func realTranscript(t *testing.T) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "updates.jsonl"))
	if err != nil {
		t.Fatalf("read transcript fixture: %v", err)
	}
	return data
}

// TestCalculateTokenUsage_DerivesFreshInput is the important one: Grok reports
// inputTokens cache-inclusive, so the fresh figure has to be derived. The
// expected values come from the same session's headless JSON summary, which
// reports the fresh input directly — so this cross-checks the derivation
// against Grok's own arithmetic rather than against itself.
func TestCalculateTokenUsage_DerivesFreshInput(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	usage, err := g.CalculateTokenUsage(realTranscript(t), 0)
	if err != nil {
		t.Fatalf("CalculateTokenUsage: %v", err)
	}
	if usage == nil {
		t.Fatal("usage is nil; the turn_completed line was not found")
	}

	// inputTokens 31658 - cachedReadTokens 15744 - cacheCreationTokens 0
	if got, want := usage.InputTokens, 15914; got != want {
		t.Errorf("InputTokens = %d, want %d (fresh input, cache excluded)", got, want)
	}
	if got, want := usage.CacheReadTokens, 15744; got != want {
		t.Errorf("CacheReadTokens = %d, want %d", got, want)
	}
	if got, want := usage.CacheCreationTokens, 0; got != want {
		t.Errorf("CacheCreationTokens = %d, want %d", got, want)
	}
	if got, want := usage.OutputTokens, 399; got != want {
		t.Errorf("OutputTokens = %d, want %d", got, want)
	}
	if got, want := usage.APICallCount, 2; got != want {
		t.Errorf("APICallCount = %d, want %d", got, want)
	}
}

// TestCalculateTokenUsage_NilWhenNoUsage distinguishes "no data" from "zero" —
// the framework treats a nil result as unknown and a zero-valued struct as a
// genuine zero.
func TestCalculateTokenUsage_NilWhenNoUsage(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	usage, err := g.CalculateTokenUsage([]byte(`{"params":{"update":{"sessionUpdate":"agent_message_chunk"}}}`), 0)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if usage != nil {
		t.Errorf("got %+v, want nil for a transcript with no usage data", usage)
	}
}

// TestCalculateTokenUsage_RespectsOffset covers the checkpoint-scoping
// contract: usage before the offset belongs to an earlier checkpoint.
func TestCalculateTokenUsage_RespectsOffset(t *testing.T) {
	t.Parallel()

	data := realTranscript(t)
	g := &GrokAgent{}

	lines, err := g.GetTranscriptPosition(filepath.Join("testdata", "updates.jsonl"))
	if err != nil {
		t.Fatalf("GetTranscriptPosition: %v", err)
	}
	usage, err := g.CalculateTokenUsage(data, lines)
	if err != nil {
		t.Fatalf("CalculateTokenUsage: %v", err)
	}
	if usage != nil {
		t.Errorf("got %+v, want nil when the offset is past every usage line", usage)
	}
}

// TestModifiedFiles_FromDiffBlocks pins file extraction to the diff content
// blocks, which carry the absolute path, rather than to locations[], which is
// relative and also present on read-only tools.
func TestModifiedFiles_FromDiffBlocks(t *testing.T) {
	t.Parallel()

	files, lines := modifiedFilesFrom(realTranscript(t), 0)
	if lines == 0 {
		t.Fatal("no lines counted")
	}
	if len(files) != 1 {
		t.Fatalf("files = %v, want exactly one", files)
	}
	if !filepath.IsAbs(files[0]) {
		t.Errorf("files[0] = %q, want an absolute path from the diff block", files[0])
	}
	if filepath.Base(files[0]) != "hello.txt" {
		t.Errorf("files[0] = %q, want basename hello.txt", files[0])
	}
}

// TestModifiedFiles_LocationsFallback covers a tool_call_update that has no
// diff block — then locations[] is the only signal available.
func TestModifiedFiles_LocationsFallback(t *testing.T) {
	t.Parallel()

	line := `{"method":"_x.ai/session/update","params":{"update":{"sessionUpdate":"tool_call_update",` +
		`"toolCallId":"c1","locations":[{"path":"src/main.go"}]}}}`
	files, _ := modifiedFilesFrom([]byte(line), 0)
	if len(files) != 1 || files[0] != "src/main.go" {
		t.Errorf("files = %v, want [src/main.go]", files)
	}
}

// TestModifiedFiles_DiffWinsOverLocations ensures the same tool call is not
// reported twice under two different spellings of the same file.
func TestModifiedFiles_DiffWinsOverLocations(t *testing.T) {
	t.Parallel()

	line := `{"method":"_x.ai/session/update","params":{"update":{"sessionUpdate":"tool_call_update",` +
		`"toolCallId":"c1","content":[{"type":"diff","path":"/abs/src/main.go"}],` +
		`"locations":[{"path":"src/main.go"}]}}}`
	files, _ := modifiedFilesFrom([]byte(line), 0)
	if len(files) != 1 {
		t.Fatalf("files = %v, want exactly one (diff should win over locations)", files)
	}
	if files[0] != "/abs/src/main.go" {
		t.Errorf("files[0] = %q, want the absolute diff path", files[0])
	}
}

// TestModifiedFiles_IgnoresNonToolUpdates guards against counting reads or
// message chunks as edits.
func TestModifiedFiles_IgnoresNonToolUpdates(t *testing.T) {
	t.Parallel()

	line := `{"method":"_x.ai/session/update","params":{"update":{"sessionUpdate":"agent_message_chunk",` +
		`"content":[{"type":"diff","path":"/abs/nope.go"}]}}}`
	files, _ := modifiedFilesFrom([]byte(line), 0)
	if len(files) != 0 {
		t.Errorf("files = %v, want none", files)
	}
}

// TestTranscriptEnvelopeIsNested is a regression guard for the shape mistake
// that costs the most: reading sessionUpdate off the top level of a line
// instead of params.update yields an empty result on every real transcript.
func TestTranscriptEnvelopeIsNested(t *testing.T) {
	t.Parallel()

	topLevel := `{"sessionUpdate":"tool_call_update","toolCallId":"c1","content":[{"type":"diff","path":"/abs/x.go"}]}`
	if files, _ := modifiedFilesFrom([]byte(topLevel), 0); len(files) != 0 {
		t.Errorf("files = %v, want none: sessionUpdate lives at params.update, not the top level", files)
	}
}

func TestGetTranscriptPosition(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}

	lines, err := g.GetTranscriptPosition(filepath.Join("testdata", "updates.jsonl"))
	if err != nil {
		t.Fatalf("GetTranscriptPosition: %v", err)
	}
	if lines != 16 {
		t.Errorf("lines = %d, want 16", lines)
	}

	// A missing file is not an error — sessions are created before their
	// transcript exists.
	missing, err := g.GetTranscriptPosition(filepath.Join("testdata", "does-not-exist.jsonl"))
	if err != nil {
		t.Errorf("missing file: unexpected error %v", err)
	}
	if missing != 0 {
		t.Errorf("missing file: got %d, want 0", missing)
	}

	if empty, err := g.GetTranscriptPosition(""); err != nil || empty != 0 {
		t.Errorf(`empty path: got (%d, %v), want (0, nil)`, empty, err)
	}
}

func TestExtractModel(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	model, err := g.ExtractModel(realTranscript(t))
	if err != nil {
		t.Fatalf("ExtractModel: %v", err)
	}
	if model != "grok-4.6" {
		t.Errorf("model = %q, want grok-4.6", model)
	}

	none, err := g.ExtractModel([]byte(`{"params":{"update":{"sessionUpdate":"tool_call"}}}`))
	if err != nil {
		t.Fatalf("ExtractModel (no model): %v", err)
	}
	if none != "" {
		t.Errorf("model = %q, want empty", none)
	}
}

func TestChunkAndReassembleRoundTrip(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	original := realTranscript(t)

	chunks, err := g.ChunkTranscript(t.Context(), original, 2048)
	if err != nil {
		t.Fatalf("ChunkTranscript: %v", err)
	}
	if len(chunks) < 2 {
		t.Fatalf("got %d chunk(s), want the fixture to actually split", len(chunks))
	}

	rejoined, err := g.ReassembleTranscript(chunks)
	if err != nil {
		t.Fatalf("ReassembleTranscript: %v", err)
	}

	// Line count is what must survive; a trailing-newline difference is not a
	// data loss.
	if got, want := len(splitJSONL(rejoined)), len(splitJSONL(original)); got != want {
		t.Errorf("round trip produced %d lines, want %d", got, want)
	}
}

func TestSplitJSONL(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		in   string
		want int
	}{
		{"empty", "", 0},
		{"one line no newline", `{"a":1}`, 1},
		{"trailing newline", "{\"a\":1}\n", 1},
		{"blank lines skipped", "{\"a\":1}\n\n{\"b\":2}\n", 2},
		{"crlf", "{\"a\":1}\r\n{\"b\":2}\r\n", 2},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := len(splitJSONL([]byte(tt.in))); got != tt.want {
				t.Errorf("splitJSONL(%q) = %d lines, want %d", tt.in, got, tt.want)
			}
		})
	}
}

package grok

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// hookRepo makes a temp dir the working directory so hooksPath resolves there.
// It cannot run in parallel: paths.WorktreeRoot falls back to the process CWD.
func hookRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	t.Chdir(dir)
	return dir
}

func installedPath(dir string) string { return filepath.Join(dir, hooksFileRelPath) }

func TestInstallHooks_WritesOwnedFile(t *testing.T) {
	dir := hookRepo(t)
	g := &GrokAgent{}
	ctx := context.Background()

	n, err := g.InstallHooks(ctx, false)
	if err != nil {
		t.Fatalf("InstallHooks: %v", err)
	}
	if n != 1 {
		t.Errorf("installed = %d, want 1", n)
	}

	data, err := os.ReadFile(installedPath(dir))
	if err != nil {
		t.Fatalf("read installed hooks: %v", err)
	}

	var file grokHooksFile
	if err := json.Unmarshal(data, &file); err != nil {
		t.Fatalf("installed hooks are not valid JSON: %v", err)
	}

	// Every verb we advertise must appear under its Grok event key, or the
	// `entire hooks grok <verb>` subcommand exists with nothing invoking it.
	for _, verb := range g.HookNames() {
		event, ok := grokEventForHook[verb]
		if !ok {
			t.Errorf("verb %q has no Grok event mapping", verb)
			continue
		}
		groups, ok := file.Hooks[event]
		if !ok || len(groups) == 0 || len(groups[0].Hooks) == 0 {
			t.Errorf("event %q missing from installed config", event)
			continue
		}
		cmd := groups[0].Hooks[0].Command
		if !strings.Contains(cmd, "entire hooks grok "+verb) {
			t.Errorf("event %q command = %q, want it to invoke verb %q", event, cmd, verb)
		}
	}
}

// TestInstallHooks_CommandsNameTheEntireBinary guards the rule that a hook must
// never run something out of the working tree: the command is executed on every
// agent turn, so a repo-relative path would let any checked-out branch run code.
func TestInstallHooks_CommandsNameTheEntireBinary(t *testing.T) {
	dir := hookRepo(t)
	g := &GrokAgent{}

	if _, err := g.InstallHooks(context.Background(), false); err != nil {
		t.Fatalf("InstallHooks: %v", err)
	}
	data, err := os.ReadFile(installedPath(dir))
	if err != nil {
		t.Fatalf("read: %v", err)
	}

	var file grokHooksFile
	if err := json.Unmarshal(data, &file); err != nil {
		t.Fatalf("parse: %v", err)
	}
	for event, groups := range file.Hooks {
		for _, g := range groups {
			for _, h := range g.Hooks {
				if !agent.IsManagedHookCommand(h.Command) {
					t.Errorf("event %q: %q is not recognised as an Entire-managed command", event, h.Command)
				}
				if strings.Contains(h.Command, dir) {
					t.Errorf("event %q: command references the working tree: %q", event, h.Command)
				}
			}
		}
	}
}

func TestInstallHooks_Idempotent(t *testing.T) {
	hookRepo(t)
	g := &GrokAgent{}
	ctx := context.Background()

	if _, err := g.InstallHooks(ctx, false); err != nil {
		t.Fatalf("first install: %v", err)
	}
	n, err := g.InstallHooks(ctx, false)
	if err != nil {
		t.Fatalf("second install: %v", err)
	}
	if n != 0 {
		t.Errorf("second install wrote %d, want 0 (already current)", n)
	}
}

func TestInstallHooks_RewritesStaleEntireConfig(t *testing.T) {
	dir := hookRepo(t)
	g := &GrokAgent{}
	ctx := context.Background()

	// A config an older CLI could have written: ours by marker, but stale.
	stale := `{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"entire hooks grok stop"}]}]}}`
	if err := os.MkdirAll(filepath.Dir(installedPath(dir)), 0o755); err != nil {
		t.Fatalf("mkdir: %v", err)
	}
	if err := os.WriteFile(installedPath(dir), []byte(stale), 0o644); err != nil {
		t.Fatalf("write stale: %v", err)
	}

	if got := g.CheckHookConfig(ctx); got != agent.HooksOutdated {
		t.Errorf("CheckHookConfig = %v, want HooksOutdated", got)
	}
	if _, err := g.InstallHooks(ctx, false); err != nil {
		t.Fatalf("InstallHooks over stale config: %v", err)
	}
	if got := g.CheckHookConfig(ctx); got != agent.HooksCurrent {
		t.Errorf("after reinstall CheckHookConfig = %v, want HooksCurrent", got)
	}
}

// TestInstallHooks_RefusesForeignFile protects a user-authored entire.json that
// happens to sit at our path.
func TestInstallHooks_RefusesForeignFile(t *testing.T) {
	dir := hookRepo(t)
	g := &GrokAgent{}
	ctx := context.Background()

	foreign := `{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"make lint"}]}]}}`
	if err := os.MkdirAll(filepath.Dir(installedPath(dir)), 0o755); err != nil {
		t.Fatalf("mkdir: %v", err)
	}
	if err := os.WriteFile(installedPath(dir), []byte(foreign), 0o644); err != nil {
		t.Fatalf("write foreign: %v", err)
	}

	if _, err := g.InstallHooks(ctx, false); err == nil {
		t.Error("expected an error installing over a foreign file")
	}
	after, err := os.ReadFile(installedPath(dir))
	if err != nil {
		t.Fatalf("read back: %v", err)
	}
	if string(after) != foreign {
		t.Error("foreign file was modified")
	}

	// --force is the documented escape hatch.
	if _, err := g.InstallHooks(ctx, true); err != nil {
		t.Fatalf("forced install: %v", err)
	}
	if !g.AreHooksInstalled(ctx) {
		t.Error("hooks not installed after --force")
	}
}

func TestAreHooksInstalledAndUninstall(t *testing.T) {
	dir := hookRepo(t)
	g := &GrokAgent{}
	ctx := context.Background()

	if g.AreHooksInstalled(ctx) {
		t.Error("hooks reported installed in a fresh repo")
	}
	if got := g.CheckHookConfig(ctx); got != agent.HooksAbsent {
		t.Errorf("CheckHookConfig = %v, want HooksAbsent", got)
	}

	if _, err := g.InstallHooks(ctx, false); err != nil {
		t.Fatalf("InstallHooks: %v", err)
	}
	if !g.AreHooksInstalled(ctx) {
		t.Error("hooks not detected after install")
	}
	if got := g.CheckHookConfig(ctx); got != agent.HooksCurrent {
		t.Errorf("CheckHookConfig = %v, want HooksCurrent", got)
	}

	if err := g.UninstallHooks(ctx); err != nil {
		t.Fatalf("UninstallHooks: %v", err)
	}
	if g.AreHooksInstalled(ctx) {
		t.Error("hooks still detected after uninstall")
	}
	if _, err := os.Stat(installedPath(dir)); !os.IsNotExist(err) {
		t.Error("hooks file still present after uninstall")
	}
}

// TestUninstallHooks_LeavesForeignFile is the counterpart to the install
// refusal: uninstall must not delete a file we never owned.
func TestUninstallHooks_LeavesForeignFile(t *testing.T) {
	dir := hookRepo(t)
	g := &GrokAgent{}

	foreign := `{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"make lint"}]}]}}`
	if err := os.MkdirAll(filepath.Dir(installedPath(dir)), 0o755); err != nil {
		t.Fatalf("mkdir: %v", err)
	}
	if err := os.WriteFile(installedPath(dir), []byte(foreign), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}

	if err := g.UninstallHooks(context.Background()); err != nil {
		t.Fatalf("UninstallHooks: %v", err)
	}
	if _, err := os.Stat(installedPath(dir)); err != nil {
		t.Error("foreign file was removed")
	}
}

func TestUninstallHooks_NoConfigIsNotAnError(t *testing.T) {
	hookRepo(t)
	g := &GrokAgent{}
	if err := g.UninstallHooks(context.Background()); err != nil {
		t.Errorf("UninstallHooks on a fresh repo: %v", err)
	}
}

func TestHookNames_MatchEventMapping(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	names := g.HookNames()
	if len(names) != len(grokEventForHook) {
		t.Errorf("HookNames has %d entries, grokEventForHook has %d", len(names), len(grokEventForHook))
	}
	seen := map[string]bool{}
	for _, n := range names {
		if seen[n] {
			t.Errorf("duplicate hook verb %q", n)
		}
		seen[n] = true
		if _, ok := grokEventForHook[n]; !ok {
			t.Errorf("verb %q has no Grok event mapping", n)
		}
	}
}

// TestRenderHooks_IsDeterministic matters because CheckHookConfig compares the
// installed file byte-for-byte against a fresh render; map iteration order
// leaking into the output would report permanent phantom drift.
func TestRenderHooks_IsDeterministic(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	first, err := renderHooks(ctx)
	if err != nil {
		t.Fatalf("renderHooks: %v", err)
	}
	for range 10 {
		next, err := renderHooks(ctx)
		if err != nil {
			t.Fatalf("renderHooks: %v", err)
		}
		if next != first {
			t.Fatal("renderHooks output varies between calls")
		}
	}
}

package grok

import (
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

func TestAgentIdentity(t *testing.T) {
	t.Parallel()

	g := NewGrokAgent()
	if got := string(g.Name()); got != "grok" {
		t.Errorf("Name = %q, want grok", got)
	}
	if got := string(g.Type()); got != "Grok Build" {
		t.Errorf("Type = %q, want Grok Build", got)
	}
	if g.Description() == "" {
		t.Error("Description is empty")
	}
	if !g.IsPreview() {
		t.Error("IsPreview = false; the integration is new and unproven at scale")
	}
	if got := g.ProtectedDirs(); len(got) != 1 || got[0] != ".grok" {
		t.Errorf("ProtectedDirs = %v, want [.grok]", got)
	}
}

func TestRegisteredInGlobalRegistry(t *testing.T) {
	t.Parallel()

	got, err := agent.Get(agent.AgentNameGrok)
	if err != nil {
		t.Fatalf("agent.Get(grok): %v", err)
	}
	if got.Type() != agent.AgentTypeGrok {
		t.Errorf("registered agent Type = %q, want %q", got.Type(), agent.AgentTypeGrok)
	}
}

func TestFormatResumeCommand(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	if got, want := g.FormatResumeCommand("abc-123"), "grok --resume abc-123"; got != want {
		t.Errorf("FormatResumeCommand = %q, want %q", got, want)
	}
}

// TestGetSessionDir_EncodesTheWorkingDirectory pins the encoding Grok uses to
// name a session group: the absolute path percent-encoded with separators
// escaped too. Getting this wrong means every transcript lookup misses.
func TestGetSessionDir_EncodesTheWorkingDirectory(t *testing.T) {
	t.Setenv("GROK_HOME", filepath.Join("/tmp", "grokhome"))

	g := &GrokAgent{}
	dir, err := g.GetSessionDir("/repo/project")
	if err != nil {
		t.Fatalf("GetSessionDir: %v", err)
	}

	group := filepath.Base(dir)
	if group != "%2Frepo%2Fproject" {
		t.Errorf("group = %q, want %%2Frepo%%2Fproject", group)
	}
	if strings.Contains(group, "/") {
		t.Errorf("group %q still contains a path separator", group)
	}
	if want := filepath.Join("/tmp", "grokhome", "sessions"); filepath.Dir(dir) != want {
		t.Errorf("parent = %q, want %q", filepath.Dir(dir), want)
	}
}

func TestEncodeCWD(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		in   string
		want string
	}{
		{"simple", "/a/b", "%2Fa%2Fb"},
		{"space", "/a b", "%2Fa%20b"},
		{"non-ascii", "/a/’b", "%2Fa%2F%E2%80%99b"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := encodeCWD(tt.in); got != tt.want {
				t.Errorf("encodeCWD(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

func TestResolveSessionFile(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	got := g.ResolveSessionFile("/base/group", "sess-1")
	want := filepath.Join("/base/group", "sess-1", "updates.jsonl")
	if got != want {
		t.Errorf("ResolveSessionFile = %q, want %q", got, want)
	}
}

// TestGetSessionDir_HonorsGrokHome matters for the E2E runner, which isolates
// every run behind its own GROK_HOME.
func TestGetSessionDir_HonorsGrokHome(t *testing.T) {
	t.Setenv("GROK_HOME", "/custom/home")

	g := &GrokAgent{}
	dir, err := g.GetSessionDir("/repo")
	if err != nil {
		t.Fatalf("GetSessionDir: %v", err)
	}
	if !strings.HasPrefix(dir, filepath.Join("/custom/home", "sessions")) {
		t.Errorf("dir = %q, want it under /custom/home/sessions", dir)
	}

	base, err := g.GetSessionBaseDir()
	if err != nil {
		t.Fatalf("GetSessionBaseDir: %v", err)
	}
	if base != filepath.Join("/custom/home", "sessions") {
		t.Errorf("base = %q, want /custom/home/sessions", base)
	}
}

func TestWriteSessionRejectsForeignAgent(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	err := g.WriteSession(t.Context(), &agent.AgentSession{
		AgentName:  agent.AgentNameClaudeCode,
		SessionRef: filepath.Join(t.TempDir(), "updates.jsonl"),
		NativeData: []byte("{}\n"),
	})
	if err == nil {
		t.Fatal("expected an error writing a Claude Code session through the Grok agent")
	}
}

func TestReadWriteSessionRoundTrip(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	ref := filepath.Join(dir, "nested", "updates.jsonl")
	data := []byte(`{"method":"_x.ai/session/update","params":{"update":{"sessionUpdate":"tool_call_update","toolCallId":"c1","content":[{"type":"diff","path":"/abs/f.go"}]}}}` + "\n")

	g := &GrokAgent{}
	if err := g.WriteSession(t.Context(), &agent.AgentSession{
		AgentName:  agent.AgentNameGrok,
		SessionRef: ref,
		NativeData: data,
	}); err != nil {
		t.Fatalf("WriteSession: %v", err)
	}

	got, err := g.ReadSession(&agent.HookInput{SessionID: "s1", SessionRef: ref})
	if err != nil {
		t.Fatalf("ReadSession: %v", err)
	}
	if string(got.NativeData) != string(data) {
		t.Error("NativeData changed across the round trip")
	}
	if len(got.ModifiedFiles) != 1 || got.ModifiedFiles[0] != "/abs/f.go" {
		t.Errorf("ModifiedFiles = %v, want [/abs/f.go]", got.ModifiedFiles)
	}
}

func TestReadSessionRequiresRef(t *testing.T) {
	t.Parallel()

	g := &GrokAgent{}
	if _, err := g.ReadSession(&agent.HookInput{SessionID: "s1"}); err == nil {
		t.Error("expected an error when SessionRef is empty")
	}
}

